<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
use Kios\Infrastructure\{Database,MenuRepository};
use Kios\Application\GopalMenuImageCatalog;
header('Content-Type: text/html; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header("Content-Security-Policy: default-src 'self'; img-src 'self'; style-src 'self'; object-src 'none'; frame-ancestors 'none'; form-action 'self'");
function esc(mixed $x):string{return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$imageFlags=json_decode((string)file_get_contents(dirname(__DIR__).'/app/Data/catalogue-image-review.json'),true,512,JSON_THROW_ON_ERROR);
function reviewPhoto($product,int $id):string { if(in_array($id,[3,4,5,6,7,8],true)&&!($product&&str_starts_with($product->imageReference??'','/assets/menu-managed/')))return '<div class="review-placeholder" role="img" aria-label="Photograph unavailable; merchant image required">Product photograph required<br>Merchant review pending</div>';return $product?GopalMenuImageCatalog::render($product):'<p>Image unavailable — merchant review required</p>'; }
$db=Database::connect();$menu=new MenuRepository($db);
$q=$db->prepare('SELECT p.product_id,p.sku,p.name,p.active,p.available,p.routing_status,c.name category,c.slug category_slug FROM products p JOIN outlets o ON o.outlet_id=p.outlet_id LEFT JOIN categories c ON c.category_id=p.category_id AND c.outlet_id=p.outlet_id WHERE o.outlet_code=:outlet ORDER BY p.product_id');$q->execute(['outlet'=>'demo-outlet']);$all=$q->fetchAll(PDO::FETCH_ASSOC);
$cat=is_string($_GET['category']??null)?$_GET['category']:'';$search=is_string($_GET['q']??null)?trim($_GET['q']):'';
$categories=[];foreach($all as $p)$categories[(string)$p['category_slug']]=(string)$p['category'];asort($categories);
$products=array_filter($all,fn($p)=>($cat===''||$p['category_slug']===$cat)&&($search===''||stripos($p['name'],$search)!==false));
$variants=$db->prepare('SELECT label,unit,quantity_value,price_paise,active FROM product_variants WHERE product_id=? ORDER BY display_order,variant_id');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Full Catalogue Review · Kios</title><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/catalogue-review.css"></head><body><header class="topbar"><a class="brand" href="/"><strong>Synthetic Restaurant Demo</strong></a><a href="/index.php" class="cart-shortcut">Ordering menu</a></header><main class="review-shell"><h1>Full Catalogue Review</h1><p><strong><?=count($all)?> catalogue products · <?=count($products)?> shown</strong></p><p>Inspection only. Visibility here does not approve a product for sale. Images are reference artwork; actual shop identity and portions require merchant review.</p><form method="get" class="review-filter"><label>Search products<input name="q" value="<?=esc($search)?>" maxlength="120" type="search"></label><label>Category<select name="category"><option value="">All Products (<?=count($all)?>)</option><?php foreach($categories as $slug=>$name):?><option value="<?=esc($slug)?>" <?=$cat===$slug?'selected':''?>><?=esc($name)?></option><?php endforeach?></select></label><button class="button button-primary">Filter catalogue</button><a href="/catalogue-review.php" class="button button-outline">All Products</a></form><section class="review-grid" aria-label="Catalogue products"><?php foreach($products as $p):$product=$menu->findBySku('demo-outlet',$p['sku']);$variants->execute([$p['product_id']]);$options=$variants->fetchAll(PDO::FETCH_ASSOC);?><article class="panel review-card" data-product-id="<?=esc($p['product_id'])?>"><div class="product-art"><?php if($product):echo reviewPhoto($product,(int)$p['product_id']);else:?><p>Image unavailable — review required</p><?php endif?></div><div class="review-info"><small>ID <?=esc($p['product_id'])?> · <?=esc($p['category'])?></small><h2><?=esc($p['name'])?></h2><p class="review-badge"><?php echo !$p['active']?'Inactive — not orderable':(!$p['available']?'Unavailable — not orderable':($p['routing_status']!=='approved'?'Route unapproved — not orderable':'Approved route — use ordering menu to order'));?></p><p><?php if($options):echo 'From INR '.number_format(min(array_column($options,'price_paise'))/100,2);else:echo 'No serving price recorded';endif?></p><details><summary>View photo and serving details</summary><div class="review-detail"><?php if($product)echo reviewPhoto($product,(int)$p['product_id']);?><p>Routing: <?=esc($p['routing_status'])?> · Availability: <?=$p['available']?'ON':'OFF'?></p><?php foreach($options as $v):?><p><?=esc($v['label'])?> · <?=esc($v['unit'])?> · INR <?=number_format($v['price_paise']/100,2)?><?=$v['active']?'':' (inactive option)'?></p><?php endforeach?><p><?=esc($imageFlags[(string)$p['product_id']]??'Reference image — merchant identity/portion approval required')?></p><p>Merchant review required. Record decisions against product ID <?=esc($p['product_id'])?>; <a href="/admin/catalogue-review.php?product_id=<?=esc($p['product_id'])?>">Owner sign-in to record a decision</a>.</p></div></details></div></article><?php endforeach?></section></main></body></html>
